        with _APPEND_LOCK, open(self.root / log, "a", encoding="utf-8", newline="\n") as handle:
            handle.write(line)

    def _read_log(self, log: str) -> Iterator[dict[str, Any]]:
        path = self.root / log
        if not path.is_file():
            return
        for line in path.read_text(encoding="utf-8").splitlines():
            if line.strip():
